def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    def group_separator(s: str) -> str:
        stack = []
        for char in s:
            if char == ' ':
                continue
            if char == '(':
                stack.append(char)
            elif char == ')':
                if len(stack) > 1:
                    stack.append(')')
                else:
                    stack.pop()
            elif not stack:
                stack.append(char)
        return ''.join(stack)

    def split_groups(s: str) -> List[str]:
        s = group_separator(s)
        groups = []
        start = 0
        for i, char in enumerate(s):
            if char == '(':
                if i > start:
                    groups.append(s[start:i])
                start = i + 1
        if start < len(s):
            groups.append(s[start:])
        return groups

    return split_groups(paren_string.replace(' ', ''))

