        cost, row, col = heapq.heappop(min_heap)
        if len(visited) == N * N:
            break

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in visited:
                visited.add((nr, nc))
                heapq.heappush(min_heap, (cost + grid[nr][nc], nr, nc))

